package net.officefloor.hq.app.person;

import java.time.LocalDate;

/** A validated hold form; {@code from} is null when left blank (the sheet's today), {@code to} null
 *  when left blank (open-ended). */
public record HoldInput(LocalDate from, LocalDate to) {
}
package net.officefloor.hq.app.person;

/** The hold form: the from-date (blank: the sheet's today) and the to-date (blank: open-ended). */
public record HoldRequest(String from, String to) {
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the hold form: a blank from-date takes the sheet's today, a blank to-date leaves the hold open-ended. */
public class ValidateHold {
    public void validate(@RequestBody HoldRequest request, Out<HoldInput> hold) throws BadRequestException {
        LocalDate from = date(request == null ? null : request.from(), "from");
        LocalDate to = date(request == null ? null : request.to(), "to");
        if (from != null && to != null && to.isBefore(from)) {
            throw new BadRequestException("to must not be before from");
        }
        hold.set(new HoldInput(from, to));
    }

    private static LocalDate date(String value, String field) throws BadRequestException {
        String raw = value == null ? "" : value.trim();
        if (raw.isEmpty()) return null;
        try {
            return LocalDate.parse(raw);
        } catch (DateTimeParseException e) {
            throw new BadRequestException(field + " must be yyyy-mm-dd");
        }
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

/** Put a person on hold from a from-date (blank: the sheet's today) to an optional to-date. A person may
 *  have several holds; each ends on its to-date. Their claims still count in every total; a hold acts
 *  only on pool cuts (a person held on the sheet's today gets no cut, their share spread over the others). */
public class HoldPerson {
    public void hold(@PathVariable("sheetId") String sheetId, @PathVariable("personId") String personId,
            @Val HoldInput input, ServerHttpConnection connection, PersonRepository repository,
            SheetRepository sheets, Audit audit, Rollup rollup, Out<Person> person) throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        long pid;
        try {
            pid = Long.parseLong(personId == null ? "" : personId.trim());
        } catch (NumberFormatException e) {
            throw new BadRequestException("no such person");
        }
        Person found = repository.find(id, pid);
        if (found == null) {
            throw new BadRequestException("no such person");
        }
        LocalDate from = input.from() != null ? input.from() : sheets.today(id);
        if (input.to() != null && input.to().isBefore(from)) {
            throw new BadRequestException("to must not be before from");
        }
        Rollup.Snapshot before = rollup.take(id);
        repository.hold(id, pid, from, input.to());
        audit.record("PERSON_HELD sheet=" + id + " by=" + by + " name=" + found.name() + " from=" + from);
        rollup.record(id, by, before);
        person.set(repository.find(id, pid));
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.LinkedHashSet;
import java.util.Set;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.settings.SettingsRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** Give the selected people a grade together, in list order (by their position), each exactly as
 *  the person form would save them with their own name and terms: the grade is recorded from the from-date
 *  (blank: the sheet's today), except that leaving the grade in force on the sheet's today as it is, with
 *  the from-date blank, records no grade; each writes PERSON_EDITED and its rollup lines. An id that is no
 *  person on the sheet is skipped. A viewer's selection is all refused: no one is graded. An archived sheet
 *  refuses it. */
public class BulkGradePeople {

    public void grade(@PathVariable("sheetId") String sheetId, @RequestBody BulkGradeRequest request,
            ServerHttpConnection connection, PersonRepository repository, SheetRepository sheets, Audit audit,
            Rollup rollup, SettingsRepository settings, Out<BulkGradeResult> result) throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        Set<Long> selected = new LinkedHashSet<>();
        if (request != null && request.personIds() != null) {
            for (Long pid : request.personIds()) {
                if (pid != null) selected.add(pid);
            }
        }
        if (selected.isEmpty()) {
            throw new BadRequestException("select at least one person");
        }
        String grade = request.grade() == null ? "" : request.grade().trim();
        settings.requireGrade(id, grade);
        String fromText = request.from() == null ? "" : request.from().trim();
        LocalDate from;
        try {
            from = fromText.isEmpty() ? sheets.today(id) : LocalDate.parse(fromText);
        } catch (DateTimeParseException e) {
            throw new BadRequestException("from-date must be yyyy-mm-dd");
        }
        if (settings.archived(id)) {
            throw new BadRequestException("the sheet is archived");
        }
        int graded = 0;
        if (settings.role(id, by).equals(SettingsRepository.VIEWER)) {
            result.set(new BulkGradeResult(graded));
            return;
        }
        if (settings.retired(id, grade)) {
            for (Person current : repository.list(id)) {
                if (selected.contains(current.id()) && (!fromText.isEmpty() || !grade.equals(current.grade()))) {
                    throw new BadRequestException("grade " + grade + " is retired");
                }
            }
        }
        for (Person current : repository.list(id)) {
            if (!selected.contains(current.id())) continue;
            boolean regrade = !fromText.isEmpty() || !grade.equals(current.grade());
            Rollup.Snapshot before = rollup.take(id);
            if (!repository.update(id, current.id(), current.version(), current.name(), current.terms())) continue;
            if (regrade) {
                repository.grade(id, current.id(), grade, from);
            }
            Person saved = repository.find(id, current.id());
            audit.record("PERSON_EDITED sheet=" + id + " by=" + by + " name=" + saved.name() + " grade=" + saved.grade());
            rollup.record(id, by, before);
            graded++;
        }
        result.set(new BulkGradeResult(graded));
    }
}
package net.officefloor.hq.app.person;

import java.util.List;

/** The bulk grade: the ids of the selected people, the grade (one of the sheet's grades) and its from-date (yyyy-mm-dd; blank for the sheet's today). */
public record BulkGradeRequest(List<Long> personIds, String grade, String from) {
}
package net.officefloor.hq.app.person;

/** How many of the selected people were given the grade. */
public record BulkGradeResult(int graded) {
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithBulkGrade {
    public void respond(@Val BulkGradeResult result, ObjectResponse<BulkGradeResult> response) {
        response.send(result);
    }
}

