import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSingleFlight } from '../../query/useSingleFlight';
import { PersonCells, PersonColumnHead } from '../../slots/defs/personRow';
import { SheetBody } from '../../slots/defs/sheetBody';
import { claimsKey } from '../claims/useClaims';
import { peopleKey, useGrades } from '../people/usePeople';
import { usePersonSelection } from './usePersonSelection';

/** A tick on the person's row that selects them for a bulk grade. */
function PersonSelect({ sheetId, personId }: { sheetId: string; personId: number }) {
  const selection = usePersonSelection(sheetId);
  const grades = useGrades(sheetId);
  return (
    <td>
      <input
        type="checkbox"
        data-testid="person-select"
        checked={selection.ids.has(personId)}
        onChange={(e) => selection.toggle(personId, e.target.checked)}
      />
    </td>
  );
}

/** Give the selected people a grade together: the server gives each, in list order, the grade from the
 *  from-date (blank: the sheet's today) exactly as the person form would; the bar shows how many were
 *  changed (gone while it runs). */
function BulkGrade({ sheetId }: { sheetId: string }) {
  const selection = usePersonSelection(sheetId);
  const grades = useGrades(sheetId);
  const queryClient = useQueryClient();
  const submitOnce = useSingleFlight();
  const [grade, setGrade] = useState<string>('A');
  const [from, setFrom] = useState('');
  const bulk = useMutation({
    mutationFn: (f: { personIds: number[]; grade: string; from: string }) =>
      postJson<{ graded: number }>(`/api/sheets/${encodeURIComponent(sheetId)}/bulk-grade`, f),
    onSuccess: () => selection.clear(),
    onSettled: async () => {
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) }),
        queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
      ]);
    },
  });
  return (
    <p data-testid="bulk-grade-bar">
      <label>
        Grade selected{' '}
        <select
          data-testid="bulk-grade"
          value={grade}
          onChange={(e) => {
            setGrade(e.target.value);
            bulk.reset();
          }}
        >
          {grades.map((g) => (
            <option key={g} value={g}>
              {g}
            </option>
          ))}
        </select>
      </label>{' '}
      <label>
        from{' '}
        <input
          type="date"
          data-testid="bulk-grade-from"
          value={from}
          onChange={(e) => {
            setFrom(e.target.value);
            bulk.reset();
          }}
        />
      </label>{' '}
      <button
        type="button"
        data-testid="bulk-grade-apply"
        disabled={bulk.isPending}
        onClick={() =>
          submitOnce(() => {
            bulk.reset();
            return bulk.mutateAsync({ personIds: [...selection.ids], grade, from });
          })
        }
      >
        Grade selected ({selection.ids.size})
      </button>
      {bulk.isSuccess && (
        <>
          {' '}
          Changed <strong data-testid="bulk-graded">{bulk.data.graded}</strong>
        </>
      )}
      {bulk.isError && <span data-testid="person-error">{bulk.error.message}</span>}
    </p>
  );
}

export const contributions = [
  PersonColumnHead.fill({ order: 1, Component: () => <th>Select</th> }),
  PersonCells.fill({ order: 1, Component: PersonSelect }),
  SheetBody.fill({ order: 12, Component: BulkGrade }),
];
import { useSyncExternalStore } from 'react';

// The people ticked for a bulk grade, per sheet. Shared by every person's row (which ticks them) and the
// bulk grade bar (which acts on them), so it lives outside any one component.
const selected = new Map<string, ReadonlySet<number>>();
const listeners = new Set<() => void>();
const NONE: ReadonlySet<number> = new Set();

function subscribe(listener: () => void) {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

function set(sheetId: string, ids: ReadonlySet<number>) {
  selected.set(sheetId, ids);
  listeners.forEach((l) => l());
}

/** The sheet's selected person ids, a way to tick or untick one, and a way to clear them all. */
export function usePersonSelection(sheetId: string) {
  const ids = useSyncExternalStore(subscribe, () => selected.get(sheetId) ?? NONE);
  const toggle = (id: number, on: boolean) => {
    const next = new Set(selected.get(sheetId) ?? NONE);
    if (on) next.add(id);
    else next.delete(id);
    set(sheetId, next);
  };
  const clear = () => set(sheetId, NONE);
  return { ids, toggle, clear };
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { PersonCells, PersonColumnHead } from '../../slots/defs/personRow';
import { peopleKey, usePeople, type Person } from '../people/usePeople';
import { poolsKey } from '../pools/usePools';
import { usePersonRowAction } from '../people/usePersonRowAction';
import { Col } from '../columns/useColumns';

/** A person's holds: whether they have any, a line per hold (from – to), and a from-date (blank: the
 *  sheet's today), an optional to-date (blank: open-ended) and a button that adds a hold. Their open
 *  (OPEN or PENDING) claims dated within a hold, unless bound by a statement, count in no live total;
 *  their other claims still do. A hold ends on its to-date. */
function PersonHold({ sheetId, personId }: { sheetId: string; personId: number }) {
  const people = usePeople(sheetId);
  const queryClient = useQueryClient();
  const p = people.data?.find((x) => x.id === personId);
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');

  const hold = useMutation({
    mutationFn: (body: { from: string; to: string }) =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${personId}/hold`, body),
    onSuccess: async () => {
      setFrom('');
      setTo('');
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
      // A hold in force on the sheet's today takes the person's cuts from the pools.
      void queryClient.invalidateQueries({ queryKey: poolsKey(sheetId) });
    },
  });
  const announce = usePersonRowAction(sheetId, personId, hold.reset);

  return (
    <>
      <Col id="hold"><td data-testid="person-hold">{p?.held ? 'yes' : 'no'}</td></Col>
      <td>
        {(p?.holds ?? []).map((h, i) => (
          <div key={i} data-testid="person-hold-line">
            {h.from ?? ''} – {h.to ?? ''}
          </div>
        ))}
      </td>
      <td>
        <input
          type="text"
          placeholder="from yyyy-mm-dd"
          data-testid="person-hold-from"
          value={from}
          onChange={(e) => {
            setFrom(e.target.value);
            hold.reset();
          }}
        />{' '}
        <input
          type="text"
          placeholder="to yyyy-mm-dd"
          data-testid="person-hold-to"
          value={to}
          onChange={(e) => {
            setTo(e.target.value);
            hold.reset();
          }}
        />{' '}
        <button
          type="button"
          data-testid="person-hold-toggle"
          disabled={hold.isPending}
          onClick={() => {
            announce();
            hold.reset();
            hold.mutate({ from: from.trim(), to: to.trim() });
          }}
        >
          Hold
        </button>
        {hold.isError && <span data-testid="person-error">{hold.error.message}</span>}
      </td>
    </>
  );
}

export const contributions = [
  PersonColumnHead.fill({
    order: 45,
    Component: () => (
      <>
        <Col id="hold"><th>Held</th></Col>
        <th>Holds</th>
        <th />
      </>
    ),
  }),
  PersonCells.fill({ order: 45, Component: PersonHold }),
];

